  ('0001eb8e-b6ad-5268-b9f9-3afc7ff7a6ff'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'FILL_IN_THE_BLANKS_DRAG_AND_DROP', E'READING', E'SHARED', NULL, E'APPROVED', '0001eb8e-b6ad-5268-b9f9-3afc7ff7a6ff'::uuid, 1, NULL, TRUE, 0, NULL, E'Evolution of Language', E'Linguists {{1}} down the evolution of language, unraveling how dialects shift and morph over time. They often {{2}} in on regional variations, documenting how populations {{3}} up new expressions while phasing out old ones. This exploration into linguistic shifts sheds {{4}} on cultural and social transformations within communities.', NULL, NULL, NULL, E'1.track, 2.zero, 3.pick, 4.light', NULL, NULL),
  ('000542ce-4e19-5abb-b109-294ae95622a8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '000542ce-4e19-5abb-b109-294ae95622a8'::uuid, 1, NULL, TRUE, 0, NULL, E'Speech Production', E'Speech production is a complex neural phenomenon that has left researchers explaining it tongue-tied. Separating out the complex web of neural regions controlling precise muscle movement in the mouth, jaw and tongue with the regions processing the auditory feedback of hearing your own voice is a complex problem.', NULL, NULL, NULL, NULL, NULL, NULL),
  ('0009546a-aaf9-529e-a107-0730ac536cc7'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '0009546a-aaf9-529e-a107-0730ac536cc7'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, 'b71e6682-d7f6-5f7b-98fb-02508d50ec43'::uuid, NULL, NULL, E'He gave a negative answer without any explanation.', NULL, NULL),
  ('000acbb6-d5bd-520b-93f5-b6c9721d7dc8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'FILL_IN_THE_BLANKS_DROPDOWN', E'FILL_IN_THE_BLANKS_DROPDOWN', E'READING', E'SHARED', NULL, E'APPROVED', '000acbb6-d5bd-520b-93f5-b6c9721d7dc8'::uuid, 1, NULL, TRUE, 0, NULL, E'Dropouts for Ph. D. s', E'Educators are seriously concerned about the high rate of dropouts among the doctor of philosophy candidates and the {{1}} loss of talent to a nation in need of Ph.D.s. Some have placed the dropouts loss as high as 50 percent. The extent of the loss was, however, largely a matter of expert guessing. Last week a well-rounded study was published. It was based on 22,000 {{2}} sent to former graduate students who were {{3}} in 24 universities and it seemed to show many past fears to be groundless.\nThe dropouts rate was found to be 31 percent, and in most cases the dropouts, while not completing the Ph.D. requirement, went on to productive work. They are not only doing well {{4}} , but, according to the report, are not far below the income levels of those who went on to complete their doctorates.', NULL, NULL, NULL, E'1.consequent, 2.questionnaires, 3.enrolled, 4.financially', NULL, NULL),
  ('0010ea14-8f24-5992-b74b-f6222f8a04f4'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'WRITE_FROM_DICTATION', E'WRITE_FROM_DICTATION', E'LISTENING', E'SHARED', NULL, E'APPROVED', '0010ea14-8f24-5992-b74b-f6222f8a04f4'::uuid, 1, NULL, TRUE, 0, NULL, E'WFD', NULL, '63897954-0704-52bd-9bae-d3bdd5a516d8'::uuid, NULL, NULL, E'The results of the study underscore the importance of the discoveries from early detection.', NULL, NULL),
