  ('00947370-57f7-59d8-b45b-7b76805897e3'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'READ_ALOUD', E'READ_ALOUD', E'SPEAKING', E'SHARED', NULL, E'APPROVED', '00947370-57f7-59d8-b45b-7b76805897e3'::uuid, 1, NULL, TRUE, 0, NULL, E'Nuclear Systems', E'Designers of new nuclear systems are adopting novel approaches in the attempt to attain success. First, they are utilizing a nuclear fuel cycle that encompasses steps from the mining of ore to the management of wastes. Second, they are evaluating systems in terms of their sustainability - meeting present needs without jeopardizing the ability of future generations to prosper.', NULL, NULL, NULL, NULL, NULL, NULL),
