  ('89e7adb6-1b5f-5045-b879-bd593ef5604c'::uuid, '003b63b3-e586-518a-b059-14c53d97431b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Women tend to prefer men who are older than they are.', FALSE, 1, NULL, NULL),
