  ('65dad86a-6af1-578e-8400-d5284a5fa29e'::uuid, '00640ca4-b82a-5f1a-8fa4-397b52bafa94'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It includes the social meanings of various aspects of life, such as race, ethnicity, values, languages, religions, and clothing styles.', FALSE, 0, NULL, NULL),
