  ('6f08d201-f414-5558-832a-ce535740dff0'::uuid, '00843311-3cc5-5243-80e2-22a08a5894d8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'However, if lobsters are capable of feeling pain, these cooking methods raise ethical questions for chefs and lobster eaters alike.', FALSE, 0, NULL, NULL),
  ('74e2ea24-1355-510b-a231-6a5b81fc4f2e'::uuid, '00843311-3cc5-5243-80e2-22a08a5894d8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This cooking technique (and others, such as storing the live lobster on ice) is used to improve humans’ dining experience.', FALSE, 1, NULL, NULL),
