  ('aad5c6ee-e7d0-5e00-99ef-90dba590c5e5'::uuid, '011b4f83-3afb-55a7-b8c7-26c1e2309735'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Birds, for instance, can struggle with mating calls and territory establishment in noisy environments.', FALSE, 0, NULL, NULL),
  ('1ef13c14-138d-5feb-bb3e-7304cc6b9f00'::uuid, '011b4f83-3afb-55a7-b8c7-26c1e2309735'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Excessive noise disrupts ecosystems, particularly affecting wildlife that relies on sound for communication and survival.', FALSE, 1, NULL, NULL),
  ('670163f5-3c5a-5e6f-9ae1-cf1f3321ee08'::uuid, '011b4f83-3afb-55a7-b8c7-26c1e2309735'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Thus, environmental noise management, such as creating quieter zones near natural habitats and regulating noise levels, becomes crucial for conservation efforts.', FALSE, 2, NULL, NULL),
  ('240d6cee-b58f-5c15-990b-67318e4d27ec'::uuid, '011b4f83-3afb-55a7-b8c7-26c1e2309735'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'This disruption can lead to decreased biodiversity of birds.', FALSE, 3, NULL, NULL),
