  ('991fe43b-2dae-57df-91f3-1058ea597e3f'::uuid, '10cfee80-3abd-527e-b00d-aec9fc743a21'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'By cultivating an observer’s stance, we could have a greater awareness of our tendencies and motivations, and we’re more likely to overcome avoidance motives.', FALSE, 1, NULL, NULL),
  ('3f4e4376-bc35-5521-94e8-81354c8c3d20'::uuid, '10cfee80-3abd-527e-b00d-aec9fc743a21'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'To overcome procrastination, we should ask ourselves whether we have checked our email and whether we are doing the task on the low-important item on our list.', FALSE, 2, NULL, NULL),
  ('c65b8ceb-e09f-5246-8f5e-0e7fe5d02b4a'::uuid, '10cfee80-3abd-527e-b00d-aec9fc743a21'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'To overcome procrastination, we should gain awareness of our approach motives or avoidance motives when doing things, which means that we need to cultivate an observer’s stance to examine ourselves.', TRUE, 3, NULL, NULL),
  ('f46a10e2-3f9a-55eb-8279-d6fdba16147a'::uuid, '110cf590-6fba-555d-a713-f37d1e58cec9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The hurricanes, which are also refers to the typhoons or cyclones, are ranked according to their wind speed and ability to cause damage.', TRUE, 0, NULL, NULL),
  ('68db4d41-18f1-53ce-b108-8d4563e421cb'::uuid, '110cf590-6fba-555d-a713-f37d1e58cec9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Comparing with the cyclone, typhoon typically begins as a tropical storm and is relatively faster in wind speed.', FALSE, 1, NULL, NULL),
  ('dafff02f-44fc-568d-aaf6-c5d60e8b2847'::uuid, '110cf590-6fba-555d-a713-f37d1e58cec9'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The majority of hurricanes last only a few days and that’s the main reason why they do not always kill people when they reach land.', FALSE, 2, NULL, NULL),
  ('26492dcf-2c55-53de-89e0-ce0c363b39e0'::uuid, '11279916-d11b-5dbc-a817-b35d85d97640'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'explain how humans grade writing.', FALSE, 0, NULL, NULL),
  ('d263a57f-7d1d-5757-84c2-a7df037c0fb0'::uuid, '11279916-d11b-5dbc-a817-b35d85d97640'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'present different methods for grading writing.', TRUE, 1, NULL, NULL),
  ('2b02c2ec-af8e-5f37-bf9a-3437309129a7'::uuid, '11279916-d11b-5dbc-a817-b35d85d97640'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'criticize the use of technology in grading writing.', FALSE, 2, NULL, NULL),
  ('5e90d016-6d39-5f24-ab7d-7268cf0fd245'::uuid, '11279916-d11b-5dbc-a817-b35d85d97640'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'describe the findings of a research project.', TRUE, 3, NULL, NULL),
  ('d8b34d8f-9cdf-5549-ae49-8d6f4d995a23'::uuid, '11279916-d11b-5dbc-a817-b35d85d97640'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'suggest directions for future research', FALSE, 4, NULL, NULL),
  ('3f526001-bc94-518c-8057-db8271d70428'::uuid, '127433c0-ead7-5872-993d-c970a2951d42'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The concept of reasonable force is very clearly defined.', FALSE, 0, NULL, NULL),
  ('f78c696b-7a6f-5a6b-a0e3-fd85d8bd3f16'::uuid, '127433c0-ead7-5872-993d-c970a2951d42'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Your use of force may be judged on how strong you are compared to the other person.', TRUE, 1, NULL, NULL),
  ('8ddafab5-da46-59d5-bfa9-2ce410c2e077'::uuid, '127433c0-ead7-5872-993d-c970a2951d42'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'If you hit someone first, you cannot then claim self-defence.', FALSE, 2, NULL, NULL),
  ('c16b73da-3b61-5f3a-95a7-2fbb41a9cf4d'::uuid, '127433c0-ead7-5872-993d-c970a2951d42'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Courts do not expect ordinary people to react rationally.', FALSE, 3, NULL, NULL),
  ('425a340e-3d26-52df-ad85-2e932dad3b43'::uuid, '154d2f98-02f4-57d4-af4e-c23a52b96d8a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The War of Independence produced among many Black Americans a heightened consciousness of the inequities in American society.', FALSE, 0, NULL, NULL),
  ('752a0dfb-020b-5f02-aed2-25b3253cf172'::uuid, '154d2f98-02f4-57d4-af4e-c23a52b96d8a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The War of Independence strengthened the bonds of slavery of many Black Americans while intensifying their desire to be free.', FALSE, 1, NULL, NULL),
  ('b84eec3a-f36a-57f0-9e23-5bc5baa6ed40'::uuid, '154d2f98-02f4-57d4-af4e-c23a52b96d8a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The War of Independence exposed to many Americans the contradiction of slavery in a country seeking its freedom and resulted in efforts to resolve that contradiction.', TRUE, 2, NULL, NULL),
  ('b1ccd99f-a761-57c7-8ee8-2177c86810c3'::uuid, '154d2f98-02f4-57d4-af4e-c23a52b96d8a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The War of Independence provoked strong criticisms by many Americans of the institution of slavery, but produced little substantive action against it.', FALSE, 3, NULL, NULL),
  ('db4c8804-e051-5f1d-ba43-a775ea1be7b8'::uuid, '161ea027-3559-5563-b5a2-51c680e553c6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The skill in the rock art is superior to that found in other parts of the world.', FALSE, 0, NULL, NULL),
  ('bc0d2ed5-9ff6-5a9c-b09d-d82c83a3f121'::uuid, '161ea027-3559-5563-b5a2-51c680e553c6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It suggests that the ancestors of the rock artists may have once lived in the same area.', FALSE, 1, NULL, NULL),
  ('1ab163f9-a3e4-5797-94b0-981c41cff6ce'::uuid, '161ea027-3559-5563-b5a2-51c680e553c6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Rock art in both places depicted animals of interest to humans.', TRUE, 2, NULL, NULL),
  ('a757c402-3251-5d41-b2bb-4a64ec3b8ea4'::uuid, '161ea027-3559-5563-b5a2-51c680e553c6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It showed the people in each place had very different lifestyles.', FALSE, 3, NULL, NULL),
  ('9e9c1420-9bda-56d8-8f93-f3a5dc750122'::uuid, '161ea027-3559-5563-b5a2-51c680e553c6'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'It shows that people in widely separated places thought the same way.', TRUE, 4, NULL, NULL),
  ('1dc1024c-bc15-58aa-a2e0-f2613cf69940'::uuid, '16e16e4a-1c0a-51bb-b1b2-9ddb49c5e247'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Anthropologists have disagreed for some time regarding when and how fire was first used in prehistoric times. Recent findings have now managed to finally persuade them that it was used before they thought and the principle use of fire was for cooking rather than any other purpose.', FALSE, 0, NULL, NULL),
  ('c78bee14-354b-5561-a66a-1c8c3c9f9646'::uuid, '16e16e4a-1c0a-51bb-b1b2-9ddb49c5e247'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Scientists believe they are now nearer to finding an answer to the question of when humans first started to use fire, and it is much earlier than had been thought. Nevertheless, there is still some disagreement among researchers around what early humans actually used the fire for.', TRUE, 1, NULL, NULL),
  ('2ab01b91-74a6-5bf6-8f89-39989ae009f7'::uuid, '16e16e4a-1c0a-51bb-b1b2-9ddb49c5e247'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'There has been much discussion by anthropologists about when humans started to use fires. As a result of a recent discovery it is thought that they started to make fires 300,000 years ago, but the reason they made them is still not clear.', FALSE, 2, NULL, NULL),
  ('d6919744-bbe8-52a3-817f-e438856b0382'::uuid, '16e16e4a-1c0a-51bb-b1b2-9ddb49c5e247'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Recent findings have convinced the anthropological community that previous conclusions from research done over many decades was correct in estimating when early humans started to use fire although this research was incorrect in its findings about what fire was used for.', FALSE, 3, NULL, NULL),
  ('f19df94f-54d2-589b-aa93-e061bfaa3d6d'::uuid, '17e64cd1-91dd-5f8c-8d6e-558945f8976c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'White blood cells are responsible for fighting pathogens inside the body. Pathogens can enter bodies and cause them to become sick. However, white blood cells are not always effective.', FALSE, 0, NULL, NULL),
  ('4815e1f1-dcad-5d3d-b213-13a362a62be6'::uuid, '17e64cd1-91dd-5f8c-8d6e-558945f8976c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'There are two major types of immune that organisms have: innate and adaptive. The skin and mucus are part of the adaptive immune system.', FALSE, 1, NULL, NULL),
  ('8847958c-a86c-5687-b4a5-59731faef478'::uuid, '17e64cd1-91dd-5f8c-8d6e-558945f8976c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The way that the immune system works is remarkably complex. Skin, the first line of defense, can keep foreign objects out of the body, while white blood cells, acting like soldiers fighting invaders, can fight pathogens in the body.', TRUE, 2, NULL, NULL),
  ('0618f6ba-09e6-5033-8161-d0d623afd02f'::uuid, '17e64cd1-91dd-5f8c-8d6e-558945f8976c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The skin, the body''s first line of defense, helps animals fight off diseases. Also, the mucus in the nose prevents airborne foreign bodies—many of which do very little good—from entering the body.', FALSE, 3, NULL, NULL),
  ('6ff7921a-027b-5d25-bfdd-ede286bfb40b'::uuid, '19198cb3-0665-5eda-82c2-d7d391fa1889'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'To enjoy a harmonious union with someone, we should ensure that we spend enough time with him or her. Also, whenever we have problems, we need to go to our best friend for support.', FALSE, 0, NULL, NULL),
  ('bd6b098b-6c90-5084-85e6-70e8bf25a732'::uuid, '19198cb3-0665-5eda-82c2-d7d391fa1889'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The chance of survival and fulfillment of a relationship will be great, if we can survive without it. When we stop believing that love alone can save us, we will truly give love a chance.', TRUE, 1, NULL, NULL),
  ('8c8e393c-54ec-5aaa-a26f-159c16b5aeef'::uuid, '19198cb3-0665-5eda-82c2-d7d391fa1889'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The demand that another person helps us with alarming and wearing things in our lives may not destroy a relationship. However, we are not encouraged to seek for help every time.', FALSE, 2, NULL, NULL),
  ('9edb5e02-582b-5888-b835-0e66d28ccbec'::uuid, '19198cb3-0665-5eda-82c2-d7d391fa1889'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Our conflicts and disappointments will at once feel more manageable when we ask our partners to support us. If they are not able to help us anymore, the relationship will be immediately broken.', FALSE, 3, NULL, NULL),
  ('05e6b9f5-1636-5cd4-847c-36d97d890ddb'::uuid, '1982a90c-34d0-504e-bf5a-190f830c413a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'products online are more affordable for those who have lost their jobs.', FALSE, 0, NULL, NULL),
  ('0b21de61-2c41-50fa-95ba-7d0a24cbe30c'::uuid, '1982a90c-34d0-504e-bf5a-190f830c413a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'the brick-and-mortar stores have yet opened due to the pandemic.', FALSE, 1, NULL, NULL),
  ('9ba40fc9-10c3-54d2-81f8-03c8e1128d99'::uuid, '1982a90c-34d0-504e-bf5a-190f830c413a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'consumers have learned how convenient it is to shop online.', TRUE, 2, NULL, NULL),
  ('fc99338b-2c2c-5f22-9a2f-523a8092c728'::uuid, '1982a90c-34d0-504e-bf5a-190f830c413a'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'there are more and more cellphones equipped with shopping apps.', FALSE, 3, NULL, NULL),
  ('1eead2ff-1ade-5cdf-9159-02e1d5729349'::uuid, '1a0aeef6-a6cd-571d-a8ae-739848d7d435'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Our genetic inheritance plays a greater role than the environment in making us who we are.', FALSE, 0, NULL, NULL),
  ('c47eaec8-b1d3-554e-b38c-37346d88be4c'::uuid, '1a0aeef6-a6cd-571d-a8ae-739848d7d435'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Our temperaments are determined by our environment.', FALSE, 1, NULL, NULL),
  ('7483ba0c-4702-5d9b-b2f6-ceb2eb3b820d'::uuid, '1a0aeef6-a6cd-571d-a8ae-739848d7d435'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Some scientists now believe intelligence is genetically determined.', TRUE, 2, NULL, NULL),
  ('bcf39889-fbf2-57f8-b715-aa88576ac3ab'::uuid, '1a0aeef6-a6cd-571d-a8ae-739848d7d435'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'All non-physical traits are inherited.', FALSE, 3, NULL, NULL),
  ('43eda694-d0a5-5822-b751-bf890dea63ae'::uuid, '1a5bce48-bfc0-55c8-a0f5-b3cec08f1974'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Children who have attended kindergarten are more interested in music.', TRUE, 0, NULL, NULL),
  ('59ddc892-06d7-5dc0-a079-12cf905acf28'::uuid, '1a5bce48-bfc0-55c8-a0f5-b3cec08f1974'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Scientists still do not know why music probably helps language learning.', FALSE, 1, NULL, NULL),
  ('301cdbb5-ec16-5d10-bb43-3de7a2d6a9f8'::uuid, '1a5bce48-bfc0-55c8-a0f5-b3cec08f1974'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Music lessons only benefit language learners who learn tonal languages.', TRUE, 2, NULL, NULL),
  ('4cd5afc2-cc79-57db-866b-f64314c32fab'::uuid, '1a5bce48-bfc0-55c8-a0f5-b3cec08f1974'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Piano lessons can heighten the brain''s response to changes in pitch.', FALSE, 3, NULL, NULL),
  ('90871fae-a0cf-5ce7-9add-76ff33ef41c6'::uuid, '1a5bce48-bfc0-55c8-a0f5-b3cec08f1974'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Mandarin is a tonal language, which is different from English.', FALSE, 4, NULL, NULL),
  ('4d7496d9-cab2-5118-b909-b16f69393d6f'::uuid, '1c4f1daf-ee8b-5342-ba33-9dbb28152b1e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'He was born in Africa.', FALSE, 0, NULL, NULL),
  ('55541bac-cec2-5eca-bc60-1f1fac51abc0'::uuid, '1c4f1daf-ee8b-5342-ba33-9dbb28152b1e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'His abilities were evident at a young age.', TRUE, 1, NULL, NULL),
  ('34df9e05-6bb7-5bb6-a90d-6500a75ca262'::uuid, '1c4f1daf-ee8b-5342-ba33-9dbb28152b1e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'He studied medicine.', FALSE, 2, NULL, NULL),
  ('c2660c69-621e-592a-8be9-9f094458ab19'::uuid, '1c4f1daf-ee8b-5342-ba33-9dbb28152b1e'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'He completed his degree in 1910.', FALSE, 3, NULL, NULL),
  ('e1b33c67-0ee2-5dfb-9d09-dae8cbf5c297'::uuid, '1d094984-f376-5cbd-a1e4-db5a6e0077f8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'There are three main interpretations of the English Revolution. The longest lasting interpretation was that the Revolution was the almost inevitable outcome of an age-old power struggle between parliament and crown. The second sees il as a class struggle, and a lead-up to the French and other revolutions. Finally, the third interpretation sees the other two as too fixed, not allowing for unpredictability, and that the outcome could have gone either way.', TRUE, 0, NULL, NULL),
  ('093f58d4-8f5b-58a8-a06d-c2a66fa03555'::uuid, '1d094984-f376-5cbd-a1e4-db5a6e0077f8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The speaker reminisces about his views of the English Revolution when he was a student and how it seemed quite clear which side he was on - the aristocrats'', not the puritans''. Later he realised there was more to it than that and there were several ways of interpreting the Revolution: as a struggle between the king and parliament, as a class war or as an unpredictable situation without clear sides.', FALSE, 1, NULL, NULL),
  ('aa8dc517-a966-558d-ab40-9db4f2e1cbc4'::uuid, '1d094984-f376-5cbd-a1e4-db5a6e0077f8'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The English Revolution has been interpreted in several ways by historians: as a fight between the aristocratic Cavaliers, who were open to life, and the serious Puritans; as a battle for power between parliament and the monarchy over the rights of Englishmen that had been going on for centuries; and as a class war similar to the French Revolution, of which it was a forerunner.', FALSE, 2, NULL, NULL),
  ('25249b18-461d-5304-8881-5430f05a162e'::uuid, '20d4c292-13e3-5f9a-9d7e-17ca499e827c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Over the last four years, NASA''s rover, Curiosity, has collected samples and taken photographs of Mars’ surface which have revealed evidence of water but has not confirmed evidence of life.', TRUE, 0, NULL, NULL),
  ('fe1f865f-70f3-56f6-a133-073ba14be5b5'::uuid, '20d4c292-13e3-5f9a-9d7e-17ca499e827c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'NASA''s rover, Curiosity, has not had recent software upgrades that have let it explore new areas of Mars looking for evidence of life.', FALSE, 1, NULL, NULL),
  ('31f32431-cdce-5280-8557-1bc80afe21c0'::uuid, '20d4c292-13e3-5f9a-9d7e-17ca499e827c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Photographs of Mars'' surface have not revealed evidence of water but have confirmed evidence of life.', FALSE, 2, NULL, NULL),
  ('041bbc6f-b8bd-5577-b4ce-0e150badf422'::uuid, '20d4c292-13e3-5f9a-9d7e-17ca499e827c'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'NASA''s rover, Curiosity, has had recent software upgrades that have let it explore new areas of Mars looking for evidence of life.', FALSE, 3, NULL, NULL),
  ('5777dc9f-1a1b-541a-809f-f4cbc59b2a64'::uuid, '20e98626-f1d3-5c48-8f8d-4834c4377743'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'needed learned people for commerce', FALSE, 0, NULL, NULL),
  ('aaa98730-973a-5e1e-9828-87ea91951e3e'::uuid, '20e98626-f1d3-5c48-8f8d-4834c4377743'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'were flourishing centers of science, literature, and other studies', TRUE, 1, NULL, NULL),
  ('878865dc-740a-5211-b3e6-7e8b2a701c35'::uuid, '20e98626-f1d3-5c48-8f8d-4834c4377743'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'attached more importance to general literacy.', TRUE, 2, NULL, NULL),
