  ('09898e7f-06fb-5728-b2e8-8f1be626b0e3'::uuid, '20e98626-f1d3-5c48-8f8d-4834c4377743'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'paid educated people better than northern cities did', FALSE, 4, NULL, NULL),
  ('b8772b07-ff97-502c-8cd7-d06bed106f74'::uuid, '23a7c0f6-961d-5c7f-b848-d45912462b7b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Pomo people were good at handwork.', FALSE, 0, NULL, NULL),
  ('47c3ef2b-9680-5329-8f4e-ca37d1577b28'::uuid, '23a7c0f6-961d-5c7f-b848-d45912462b7b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They used limited materials in their work.', FALSE, 1, NULL, NULL),
  ('2a5d1093-8e1a-58e6-82b1-33d9d1a13868'::uuid, '23a7c0f6-961d-5c7f-b848-d45912462b7b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Their baskets have various designs.', FALSE, 2, NULL, NULL),
  ('ae338c45-1cf4-574e-8988-9a458e41d8ce'::uuid, '23a7c0f6-961d-5c7f-b848-d45912462b7b'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'They seldom used sedge root in their work.', TRUE, 3, NULL, NULL),
