  ('f63a2614-4276-5da2-8acc-5830c31718e0'::uuid, '2448cbe1-856f-5fc3-be73-d017adf3d663'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Germany', FALSE, 5, NULL, NULL),
  ('4d7ed370-1636-5730-b4bf-16b55d00f92c'::uuid, '2739249f-b3e9-599c-a696-c25c8669881d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Fossil legs of early whales are a rare find.', FALSE, 0, NULL, NULL),
  ('61b1f554-0c71-51a5-9741-2abd9dd87489'::uuid, '2739249f-b3e9-599c-a696-c25c8669881d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The legs provided important information about the evolution of cetaceans.', TRUE, 1, NULL, NULL),
  ('bc4cdf95-6a3b-57a8-88aa-cab7178a24b4'::uuid, '2739249f-b3e9-599c-a696-c25c8669881d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The discovery allowed scientists to reconstruct a complete evolution of the whale.', TRUE, 2, NULL, NULL),
  ('76bc9395-adc0-570b-be84-79f4889813b1'::uuid, '2739249f-b3e9-599c-a696-c25c8669881d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Until that time, only the front legs of early whales had been discovered.', FALSE, 3, NULL, NULL),
  ('042bb58b-85e5-5006-80d0-217680795465'::uuid, '2739249f-b3e9-599c-a696-c25c8669881d'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The scientists took more than a decade to find the fossil.', FALSE, 4, NULL, NULL);
INSERT INTO _pte_local_seed_options (public_id, question_public_id, created_at, updated_at, deleted, text, correct, order_index, blank_index, correct_gap_index) VALUES
  ('087526f2-6ef6-5aa0-b005-e1481d0f8c3a'::uuid, '27556383-0a8b-5658-9e04-ed17acea9b47'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Many existing buildings in city centres, such as Perth are being cleared to make way for modern developments.  Although this is improving the visual impact of the city, it is causing difficulties in areas where there is not enough space to accommodate the expanding population.', FALSE, 0, NULL, NULL),
  ('beb82da4-62ca-5196-a7e9-e232d2f1e76e'::uuid, '27556383-0a8b-5658-9e04-ed17acea9b47'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Developers in Perth and other parts of Western Australia are suggesting that it would be better to build much-needed homes within the city centre, as this would be more affordable for local people. It would also make transportation to and from jobs and shops cheaper and quicker.', FALSE, 1, NULL, NULL),
  ('d37cdedf-a05f-53ed-824f-599078236126'::uuid, '27556383-0a8b-5658-9e04-ed17acea9b47'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Cities like Perth in Western Australia are experiencing a rapid growth in urban development. and the current trend is to expand into surrounding regions. Although some people think this is more cost-effective than building within cities, others believe it''s having a harmful effect on the environment in these areas.', TRUE, 2, NULL, NULL),
  ('d8e04c2d-c017-5da8-b12b-09c94fd8f498'::uuid, '27556383-0a8b-5658-9e04-ed17acea9b47'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The housing shortage in Perth is being addressed by encouraging people to move to other cities in Western Australia where there is more space to develop new housing and infrastructure. This will benefit people struggling to find accommodation and also avoid having to develop on bushland.', FALSE, 3, NULL, NULL),
  ('aded8dc1-de85-5696-a5f8-43841323a749'::uuid, '27b51cff-c2f7-566b-bbe5-e63c4abfc6dd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'hasn''t been signed yet', FALSE, 0, NULL, NULL),
  ('1efeea54-3c60-5c2e-a036-db347009a822'::uuid, '27b51cff-c2f7-566b-bbe5-e63c4abfc6dd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'provides $45 billion for animals', FALSE, 1, NULL, NULL),
  ('9cd46ae8-2970-5cf0-a463-0427b28f3faa'::uuid, '27b51cff-c2f7-566b-bbe5-e63c4abfc6dd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'supports that treatable animals should not be euthanized', TRUE, 2, NULL, NULL),
  ('9910d298-b19c-5e30-a317-627a7799abdd'::uuid, '27b51cff-c2f7-566b-bbe5-e63c4abfc6dd'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'is useless for improving the status of stray animals', FALSE, 3, NULL, NULL),
  ('9a4946b5-6145-5635-9635-461f88f1c13a'::uuid, '29124ebc-ff36-586a-bdec-27ece0d7dd77'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Eating out is the number one purchase people say they regret. It is very hard to save money from it, because it’s a frequent purchase that we make almost everyday.', FALSE, 0, NULL, NULL),
  ('623a668f-9351-5589-91df-925c2216d9c4'::uuid, '29124ebc-ff36-586a-bdec-27ece0d7dd77'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Our brains are very good at counting up the number of times we’ve done something. So each time we save some money, our brain will retain the memory, and thus we’ll be more motivated to save more money.', FALSE, 1, NULL, NULL),
  ('c0348bef-4ec6-5a0a-965a-3a7345f03ece'::uuid, '29124ebc-ff36-586a-bdec-27ece0d7dd77'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'In cities like New York, the bike-sharing expense is almost as high as house rent. Therefore, the best way to save money in big cities is to walk to the office or travel on foot.', FALSE, 2, NULL, NULL),
  ('f5211947-bf2d-5491-ad64-5326253b7fcd'::uuid, '29124ebc-ff36-586a-bdec-27ece0d7dd77'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'To save money, a crucial step is to change our environment. The environmental changes can make it harder for us to make a purchase, and thus help us to save money.', TRUE, 3, NULL, NULL),
  ('617e31fb-2daa-5562-893d-8820c506d73f'::uuid, '2b619c62-f062-5403-8ec5-f61c6f0fde31'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The capacity to create shade', TRUE, 0, NULL, NULL),
  ('fdb56db7-7b88-50f0-b350-8ea096d638b8'::uuid, '2b619c62-f062-5403-8ec5-f61c6f0fde31'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'Leaves containing tannin', TRUE, 1, NULL, NULL),
  ('e3c2a60b-a5a9-5894-92de-774e99ec099a'::uuid, '2b619c62-f062-5403-8ec5-f61c6f0fde31'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The ability to withstand mild droughts and fire', TRUE, 2, NULL, NULL),
  ('d98b116c-3e2e-5394-a8d6-b154c0e01abb'::uuid, '2b619c62-f062-5403-8ec5-f61c6f0fde31'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The large number of acorns the tree produces', FALSE, 3, NULL, NULL),
  ('926bf322-d83f-5222-b23a-c02a3228ecb2'::uuid, '2b619c62-f062-5403-8ec5-f61c6f0fde31'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'The abilities to produce thousands of tasty acorns', FALSE, 4, NULL, NULL),
  ('cb3ed0d0-ebb0-55d9-a7f1-053b08d8bb20'::uuid, '2b62ffb9-bb5c-52e9-a7c1-3051a47c8c85'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'To argue that wind farms should not be built along ridge lines', FALSE, 0, NULL, NULL),
  ('7ec865e7-56ff-5fd5-b45b-5b2946d3d121'::uuid, '2b62ffb9-bb5c-52e9-a7c1-3051a47c8c85'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'To point out that the deaths of migratory birds exceed the deaths of birds of prey', FALSE, 1, NULL, NULL),
  ('d5ad16f2-0bc4-52f4-8705-7f200a353425'::uuid, '2b62ffb9-bb5c-52e9-a7c1-3051a47c8c85'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'To explain why some environmentalists oppose wind energy', FALSE, 2, NULL, NULL),
  ('ebfd6b6d-be8e-5b99-94d3-be6d23bde35d'::uuid, '2b62ffb9-bb5c-52e9-a7c1-3051a47c8c85'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'To demonstrate the number of birds killed by wind turbines is overestimated', TRUE, 3, NULL, NULL),
  ('68c29f44-89e1-5e4a-8162-3456a2ecef5d'::uuid, '2b62ffb9-bb5c-52e9-a7c1-3051a47c8c85'::uuid, TIMESTAMPTZ '2026-09-23 00:00:00+00', TIMESTAMPTZ '2026-09-23 00:00:00+00', FALSE, E'To suggest that wind turbines result in relatively few bird deaths', TRUE, 4, NULL, NULL);
