-- LOCAL-ONLY question seed; generated data is not a Flyway migration.
-- It is intentionally not executed by this generator. Review before running with psql.
-- Source: data/question-import/by-task-type/*.json
-- Seed status: APPROVED; questions with unresolved import warnings are excluded.
-- Included questions: 150; options: 522; media: 80.
-- External media URLs are stored in media_objects.secure_url and referenced by UUID.

BEGIN;
SET LOCAL lock_timeout = '5s';

DO $$
DECLARE missing_columns TEXT;
BEGIN
    IF to_regclass('public.questions') IS NULL THEN
        RAISE EXCEPTION 'questions table is missing; run the application migrations first';
    END IF;
    IF to_regclass('public.question_options') IS NULL THEN
        RAISE EXCEPTION 'question_options table is missing; run the application migrations first';
    END IF;
    IF to_regclass('public.media_objects') IS NULL THEN
        RAISE EXCEPTION 'media_objects table is missing; run the application migrations first';
    END IF;
    IF to_regclass('public.question_types') IS NULL THEN
        RAISE EXCEPTION 'question_types table is missing; run the application migrations first';
    END IF;
    SELECT string_agg(required_column.table_name || '.' || required_column.column_name, ' , '
                       ORDER BY required_column.table_name, required_column.column_name)
      INTO missing_columns
      FROM (VALUES
          ('questions', 'task_type_key'),
          ('questions', 'task_type_section'),
          ('questions', 'revision_group_public_id'),
          ('questions', 'revision_number'),
          ('questions', 'is_current'),
          ('questions', 'version'),
          ('questions', 'audio_prompt_ref'),
          ('questions', 'image_prompt_ref'),
          ('question_options', 'blank_index'),
          ('question_options', 'correct_gap_index'),
          ('media_objects', 'cloudinary_public_id'),
          ('media_objects', 'cloudinary_resource_type'),
          ('media_objects', 'secure_url'),
          ('media_objects', 'asset_id'),
          ('media_objects', 'size_bytes'),
          ('question_types', 'task_type_key')
      ) AS required_column(table_name, column_name)
     WHERE NOT EXISTS (
         SELECT 1
           FROM information_schema.columns column_info
          WHERE column_info.table_schema = 'public'
            AND column_info.table_name = required_column.table_name
            AND column_info.column_name = required_column.column_name
     );
    IF missing_columns IS NOT NULL THEN
        RAISE EXCEPTION 'Required schema columns are missing: %', missing_columns;
    END IF;
END $$;

CREATE TEMP TABLE _pte_local_seed_media (
    public_id UUID PRIMARY KEY,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    deleted BOOLEAN NOT NULL,
    tenant_id UUID,
    owner_public_id UUID NOT NULL,
    content_type VARCHAR(255) NOT NULL,
    storage_key VARCHAR(255) NOT NULL,
    status VARCHAR(32) NOT NULL,
    audio_prompt BOOLEAN NOT NULL,
    duration_seconds INTEGER,
    cloudinary_public_id VARCHAR(512),
    cloudinary_resource_type VARCHAR(32),
    secure_url TEXT,
    asset_id VARCHAR(255),
    size_bytes BIGINT
) ON COMMIT DROP;

CREATE TEMP TABLE _pte_local_seed_questions (
    question_public_id UUID PRIMARY KEY,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    deleted BOOLEAN NOT NULL,
    pte_task_type VARCHAR(64),
    task_type_key VARCHAR(64) NOT NULL,
    task_type_section VARCHAR(16) NOT NULL,
    visibility VARCHAR(16) NOT NULL,
    tenant_id UUID,
    status VARCHAR(16) NOT NULL,
    revision_group_public_id UUID NOT NULL,
    revision_number INTEGER NOT NULL,
    supersedes_public_id UUID,
    is_current BOOLEAN NOT NULL,
    version BIGINT NOT NULL,
    rejection_reason VARCHAR(500),
    title VARCHAR(255) NOT NULL,
    prompt_text TEXT,
    audio_prompt_ref UUID,
    image_prompt_ref UUID,
    reference_answer_text TEXT,
    correct_answer_text TEXT,
    min_word_count INTEGER,
    max_word_count INTEGER
) ON COMMIT DROP;

CREATE TEMP TABLE _pte_local_seed_options (
    public_id UUID PRIMARY KEY,
    question_public_id UUID NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    deleted BOOLEAN NOT NULL,
    text TEXT NOT NULL,
    correct BOOLEAN NOT NULL,
    order_index INTEGER NOT NULL,
    blank_index INTEGER,
    correct_gap_index INTEGER
) ON COMMIT DROP;





DO $$
DECLARE missing_task_types TEXT;
BEGIN
    SELECT string_agg(seed.task_type_key, ' , ' ORDER BY seed.task_type_key)
      INTO missing_task_types
      FROM (SELECT DISTINCT task_type_key FROM _pte_local_seed_questions) seed
     WHERE NOT EXISTS (
         SELECT 1 FROM question_types definition
          WHERE definition.task_type_key = seed.task_type_key AND definition.deleted = FALSE
     );
    IF missing_task_types IS NOT NULL THEN
        RAISE EXCEPTION 'Missing question type catalog row(s): %', missing_task_types;
    END IF;
END $$;

    public_id, created_at, updated_at, deleted, tenant_id, owner_public_id, content_type,
    storage_key, status, audio_prompt, duration_seconds, cloudinary_public_id,
    cloudinary_resource_type, secure_url, asset_id, size_bytes
)
SELECT public_id, created_at, updated_at, deleted, tenant_id, owner_public_id, content_type,
       storage_key, status, audio_prompt, duration_seconds, cloudinary_public_id,
       cloudinary_resource_type, secure_url, asset_id, size_bytes
  FROM _pte_local_seed_media
ON CONFLICT (public_id) DO UPDATE SET
    updated_at = EXCLUDED.updated_at, deleted = EXCLUDED.deleted, tenant_id = EXCLUDED.tenant_id,
    owner_public_id = EXCLUDED.owner_public_id, content_type = EXCLUDED.content_type,
    storage_key = EXCLUDED.storage_key, status = EXCLUDED.status,
    audio_prompt = EXCLUDED.audio_prompt, duration_seconds = EXCLUDED.duration_seconds,
    cloudinary_public_id = EXCLUDED.cloudinary_public_id,
    cloudinary_resource_type = EXCLUDED.cloudinary_resource_type,
    secure_url = EXCLUDED.secure_url, asset_id = EXCLUDED.asset_id, size_bytes = EXCLUDED.size_bytes;

    public_id, created_at, updated_at, deleted, pte_task_type, task_type_key, task_type_section,
    visibility, tenant_id, status, revision_group_public_id, revision_number, supersedes_public_id,
    is_current, version, rejection_reason, title, prompt_text, audio_prompt_ref, image_prompt_ref,
    reference_answer_text, correct_answer_text, min_word_count, max_word_count
)
SELECT question_public_id, created_at, updated_at, deleted, pte_task_type, task_type_key,
       task_type_section, visibility, tenant_id, status, revision_group_public_id, revision_number,
       supersedes_public_id, is_current, version, rejection_reason, title, prompt_text,
       audio_prompt_ref, image_prompt_ref, reference_answer_text, correct_answer_text,
       min_word_count, max_word_count
  FROM _pte_local_seed_questions
ON CONFLICT (public_id) DO UPDATE SET
    updated_at = EXCLUDED.updated_at, deleted = EXCLUDED.deleted,
    pte_task_type = EXCLUDED.pte_task_type, task_type_key = EXCLUDED.task_type_key,
    task_type_section = EXCLUDED.task_type_section, visibility = EXCLUDED.visibility,
    tenant_id = EXCLUDED.tenant_id, status = EXCLUDED.status,
    revision_group_public_id = EXCLUDED.revision_group_public_id, revision_number = EXCLUDED.revision_number,
    supersedes_public_id = EXCLUDED.supersedes_public_id, is_current = EXCLUDED.is_current,
    version = EXCLUDED.version, rejection_reason = EXCLUDED.rejection_reason, title = EXCLUDED.title,
    prompt_text = EXCLUDED.prompt_text, audio_prompt_ref = EXCLUDED.audio_prompt_ref,
    image_prompt_ref = EXCLUDED.image_prompt_ref, reference_answer_text = EXCLUDED.reference_answer_text,
    correct_answer_text = EXCLUDED.correct_answer_text, min_word_count = EXCLUDED.min_word_count,
    max_word_count = EXCLUDED.max_word_count;

DELETE FROM question_options existing
 USING questions question
 JOIN _pte_local_seed_questions seed ON seed.question_public_id = question.public_id
 WHERE existing.question_id = question.id;

    public_id, created_at, updated_at, deleted, question_id, text, correct, order_index,
    blank_index, correct_gap_index
)
SELECT seed_option.public_id, seed_option.created_at, seed_option.updated_at, seed_option.deleted,
       question.id, seed_option.text, seed_option.correct, seed_option.order_index,
       seed_option.blank_index, seed_option.correct_gap_index
  FROM _pte_local_seed_options seed_option
  JOIN questions question ON question.public_id = seed_option.question_public_id
ON CONFLICT (public_id) DO UPDATE SET
    updated_at = EXCLUDED.updated_at, deleted = EXCLUDED.deleted, question_id = EXCLUDED.question_id,
    text = EXCLUDED.text, correct = EXCLUDED.correct, order_index = EXCLUDED.order_index,
    blank_index = EXCLUDED.blank_index, correct_gap_index = EXCLUDED.correct_gap_index;

DO $$
DECLARE question_count BIGINT; option_count BIGINT;
BEGIN
    SELECT COUNT(*) INTO question_count
      FROM questions question JOIN _pte_local_seed_questions seed
        ON seed.question_public_id = question.public_id;
    SELECT COUNT(*) INTO option_count
      FROM question_options option JOIN _pte_local_seed_options seed
        ON seed.public_id = option.public_id;
    IF question_count <> 150 OR option_count <> 522 THEN
        RAISE EXCEPTION 'Local question seed verification failed: questions=%, options=%', question_count, option_count;
    END IF;
END $$;

-- Audio duration is required for the dynamic preparation window of the five
-- audio-prompt Speaking task types used by the local full-skill demo.
DO $$
DECLARE updated_media_count INTEGER;
BEGIN
    UPDATE media_objects
    SET duration_seconds = CASE public_id
        WHEN '3b90fbbe-0756-5338-bee1-d201b672a7a1'::uuid THEN 6
        WHEN '8fc9b4c6-261c-5176-8c1b-5b19a69f938f'::uuid THEN 72
        WHEN '452e2a9d-2841-56b7-8b2b-5e0091bc5b86'::uuid THEN 4
        WHEN '8212261c-d432-4f9b-a171-e6f015c26029'::uuid THEN 81
        WHEN 'b9bef14e-4ca9-5af4-88ca-8014f73543fa'::uuid THEN 15
        ELSE duration_seconds
    END
    WHERE public_id IN (
        '3b90fbbe-0756-5338-bee1-d201b672a7a1'::uuid,
        '8fc9b4c6-261c-5176-8c1b-5b19a69f938f'::uuid,
        '452e2a9d-2841-56b7-8b2b-5e0091bc5b86'::uuid,
        '8212261c-d432-4f9b-a171-e6f015c26029'::uuid,
        'b9bef14e-4ca9-5af4-88ca-8014f73543fa'::uuid
    );

    GET DIAGNOSTICS updated_media_count = ROW_COUNT;
    IF updated_media_count <> 5 THEN
        RAISE EXCEPTION 'Local audio duration metadata update expected 5 rows but updated %', updated_media_count;
    END IF;
END $$;

COMMIT;
